import { Box, Typography, TextField, Button, Stack, Divider, List, ListItem, ListItemText, FormControl, InputLabel, MenuItem, Select } from '@mui/material';
import { useState } from 'react';
import MinimalAppBar from '../../Component/MinimalAppBar';
import PaymentHistory from './PaymentHistory';

export default function PaymentScreen() {


  const [contract, setContract] = useState('');
  const [slip, setSlip] = useState(null);
  const [history, setHistory] = useState([
    { date: '2025-08-01', amount: '฿1,000', status: 'ชำระแล้ว', contract: 'สัญญา A' },
    { date: '2025-07-01', amount: '฿1,000', status: 'ชำระแล้ว', contract: 'สัญญา B' },
  ]);

  const handleSlipUpload = (e:any) => {
    // setSlip(URL.createObjectURL(e.target.files[0]));
  };

  return (
    <>
    <MinimalAppBar title='ชำระเงิน' onBack={function (): void {
              throw new Error('Function not implemented.');
          } } />


    <Box sx={{ p: 3, maxWidth: 600, mx: 'auto' }}>
      <Typography variant="h5" gutterBottom>ชำระเงิน</Typography>

      <Stack spacing={2}>
        <FormControl fullWidth>
          <InputLabel>เลือกสัญญา</InputLabel>
          <Select
            value={contract}
            label="เลือกสัญญา"
            onChange={(e) => setContract(e.target.value)}
          >
            <MenuItem value="สัญญา A">สัญญา A</MenuItem>
            <MenuItem value="สัญญา B">สัญญา B</MenuItem>
            <MenuItem value="สัญญา C">สัญญา C</MenuItem>
          </Select>
        </FormControl>

        <TextField label="จำนวนเงินที่โอน (บาท)" variant="outlined" fullWidth />

        <Button variant="contained" component="label">
          แนบสลิปการโอน
          <input type="file" hidden onChange={handleSlipUpload} />
        </Button>

        {slip && (
          <Box sx={{ mt: 1 }}>
            <Typography variant="body2">สลิปที่แนบ:</Typography>
            <img src={slip} alt="slip" style={{ width: '100%', borderRadius: 8 }} />
          </Box>
        )}

        <Button variant="contained" color="success">ยืนยันการชำระเงิน</Button>
      </Stack>

      <Divider sx={{ my: 4 }} />

        <PaymentHistory />
    </Box>

    </>
  );
}
